-- Migration: indexes and integrity constraints for chamber_audit_packs
-- Checksum+scope composite index, partial checksum-present index, non-empty scope check.
-- Idempotent: safe to re-run.

CREATE INDEX IF NOT EXISTS idx_chamber_audit_packs_checksum_scope
    ON chamber_audit_packs (checksum, scope);

CREATE INDEX IF NOT EXISTS idx_chamber_audit_packs_signed_packs
    ON chamber_audit_packs (generated_at DESC, scope)
    WHERE checksum IS NOT NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'chk_chamber_audit_packs_scope_not_blank'
        AND conrelid = 'chamber_audit_packs'::regclass
    ) THEN
        ALTER TABLE chamber_audit_packs
            ADD CONSTRAINT chk_chamber_audit_packs_scope_not_blank CHECK (char_length(btrim(scope)) > 0);
    END IF;
END;
$$;
