```python
"""Aggregate summary service for Factsheet records.

Reads ``chamber_vendor_factsheets`` and joins ``chamber_vendors`` on
``vendor_id`` to attach vendor name and sector. Derives factsheet counts per
sector, the share of vendors covered by at least one factsheet, and the most
recent ``generated_at`` timestamp per sector.

Validation style: lenient — a loosely typed cutoff is coerced with a warning.
Return style: a plain dict; query failures raise ``RuntimeError``.
"""
from __future__ import annotations

import logging
from datetime import datetime
from typing import Any, Dict, List, Optional

from database import supabase

logger = logging.getLogger(__name__)


def _coerce_cutoff(generated_after: Any) -> Optional[str]:
    """Coerce a date-ish value to an ISO string, warning on bad input."""
    if generated_after is None:
        return None
    if isinstance(generated_after, datetime):
        return generated_after.isoformat()
    if isinstance(generated_after, str) and generated_after.strip():
        return generated_after.strip()
    logger.warning("factsheet aggregate: uninterpretable cutoff %r, ignoring", generated_after)
    return None


def summarize_factsheets(generated_after: Any = None) -> Dict[str, Any]:
    """Summarise factsheet coverage across vendors.

    Args:
        generated_after: Optional ISO timestamp / datetime; rows older than
            this are skipped. Bad values are ignored with a warning.

    Returns:
        A dict with per-sector counts, vendor coverage and latest timestamps.

    Raises:
        RuntimeError: If a query fails.
    """
    cutoff = _coerce_cutoff(generated_after)

    try:
        fs_resp = (
            supabase.table("chamber_vendor_factsheets")
            .select("vendor_id, summary, generated_at")
            .execute()
        )
    except Exception as exc:
        raise RuntimeError(f"failed to load factsheets: {exc}") from exc

    factsheets: List[Dict[str, Any]] = fs_resp.data or []

    vendor_ids = sorted({f["vendor_id"] for f in factsheets if f.get("vendor_id")})
    vendor_meta: Dict[str, Dict[str, Any]] = {}
    if vendor_ids:
        try:
            v_resp = (
                supabase.table("chamber_vendors")
                .select("id, name, sector")
                .in_("id", vendor_ids)
                .execute()
            )
            for vendor in v_resp.data or []:
                vendor_meta[vendor["id"]] = {
                    "name": vendor.get("name") or "(unnamed)",
                    "sector": vendor.get("sector") or "unassigned",
                }
        except Exception as exc:
            logger.warning("factsheet aggregate: vendor lookup failed: %s", exc)

    try:
        total_vendors = (
            supabase.table("chamber_vendors").select("id", count="exact").execute().count
        ) or 0
    except Exception as exc:
        logger.warning("factsheet aggregate: vendor count failed: %s", exc)
        total_vendors = 0

    by_sector: Dict[str, int] = {}
    latest_by_sector: Dict[str, str] = {}
    covered_vendors = set()

    for fs in factsheets:
        gen_at = fs.get("generated_at")
        if cutoff and isinstance(gen_at, str) and gen_at < cutoff:
            continue
        sector = vendor_meta.get(fs.get("vendor_id"), {}).get("sector", "unassigned")
        by_sector[sector] = by_sector.get(sector, 0) + 1
        if fs.get("vendor_id"):
            covered_vendors.add(fs["vendor_id"])
        if isinstance(gen_at, str):
            current = latest_by_sector.get(sector)
            if current is None or gen_at > current:
                latest_by_sector[sector] = gen_at

    return {
        "total_factsheets": sum(by_sector.values()),
        "factsheets_by_sector": by_sector,
        "vendors_with_factsheet": len(covered_vendors),
        "vendor_coverage_pct": round((len(covered_vendors) / total_vendors) * 100, 2)
        if total_vendors
        else 0.0,
        "latest_generated_at_by_sector": latest_by_sector,
    }
```

