-- Migration: derive search text and gate proposal status by composite score on chamber_proposals.

CREATE OR REPLACE FUNCTION chamber_proposals_score_gate_fn()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.composite_score IS NOT NULL
       AND (NEW.composite_score < 0 OR NEW.composite_score > 100) THEN
        RAISE EXCEPTION 'composite_score % out of range [0,100]', NEW.composite_score;
    END IF;

    NEW.search_text := lower(
        COALESCE(NEW.title, '') || ' ' ||
        COALESCE(NEW.sector, '') || ' ' ||
        COALESCE(NEW.technology_type, '')
    );

    IF NEW.composite_score IS NOT NULL AND NEW.composite_score >= 80
       AND NEW.status NOT IN ('rejected', 'withdrawn') THEN
        NEW.status := 'shortlisted';
    END IF;

    NEW.updated_at := now();

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_chamber_proposals_score_gate ON chamber_proposals;

CREATE TRIGGER trg_chamber_proposals_score_gate
    BEFORE INSERT OR UPDATE ON chamber_proposals
    FOR EACH ROW
    EXECUTE FUNCTION chamber_proposals_score_gate_fn();
```

