```python
"""Tests for the Pilot service create path (`backend/tests/test_pilot_service.py`).

The supabase client is fully mocked, so this suite runs without a database.
The function under test is lenient about its inputs -- it coerces questionable
values and logs a warning -- but it raises on a persistence error (an empty
result or a client exception).
"""
from __future__ import annotations

import logging
from types import SimpleNamespace

import pytest


class PilotServiceError(RuntimeError):
    """Raised when persisting a pilot fails or returns no row."""


class _FakeQuery:
    """Chained query-builder stub that records insert/update payloads."""

    def __init__(self, table):
        self._table = table

    def insert(self, payload):
        self._table.calls.append(("insert", payload))
        self._table.last_insert = payload
        return self

    def update(self, payload):
        self._table.calls.append(("update", payload))
        self._table.last_update = payload
        return self

    def select(self, *args, **kwargs):
        return self

    def eq(self, column, value):
        self._table.filters.append((column, value))
        return self

    def maybe_single(self):
        return self

    def order(self, *args, **kwargs):
        return self

    def limit(self, *args, **kwargs):
        return self

    def execute(self):
        if self._table.raise_exc is not None:
            raise self._table.raise_exc
        return _FakeResponse(self._table.return_rows)


class _FakeResponse:
    def __init__(self, data):
        self.data = data


class _FakeTable:
    def __init__(self):
        self.calls = []
        self.filters = []
        self.last_insert = None
        self.last_update = None
        self.return_rows = None
        self.raise_exc = None


class FakeSupabase:
    """Minimal stand-in for the supabase client used by the service layer."""

    def __init__(self):
        self.tables = {}
        self.table_names = []

    def table(self, name):
        self.table_names.append(name)
        return _FakeQuery(self.tables.setdefault(name, _FakeTable()))

    def tbl(self, name):
        return self.tables.setdefault(name, _FakeTable())

logger = logging.getLogger("pilot_service")


def create_pilot(*, proposal_id="<UUID>", vendor_id="<UUID>", status="open", success_criteria="15% loss reduction in 90 days", budget_allocated=250000.0, db=None):
    """Insert a pilot row into `chamber_pilots`, raising PilotServiceError on failure.

    Lenient validation: a stray string status is stripped, and the
    `budget_allocated` field is coerced to its expected type with a warning rather
    than rejected.
    """
    if isinstance(status, str):
        status = status.strip()
    if budget_allocated is not None and isinstance(budget_allocated, str):
        logger.warning("coercing budget_allocated from string %r", budget_allocated)
        try:
            budget_allocated = float(budget_allocated)
        except (TypeError, ValueError):
            logger.warning("could not coerce budget_allocated; defaulting to 0")
            budget_allocated = float(0)

    payload = {
        "proposal_id": proposal_id,
        "vendor_id": vendor_id,
        "status": status,
        "success_criteria": success_criteria,
        "budget_allocated": budget_allocated,
    }

    try:
        result = db.table("chamber_pilots").insert(payload).execute()
    except Exception as exc:  # noqa: BLE001 - re-raised as a domain error
        logger.error("insert into chamber_pilots failed: %s", exc)
        raise PilotServiceError("failed to persist pilot") from exc

    rows = result.data or []
    if not rows:
        raise PilotServiceError("insert into chamber_pilots returned no rows")
    return rows[0]


PilotService = SimpleNamespace(create_pilot=create_pilot)


@pytest.fixture()
def fake_db():
    return FakeSupabase()


@pytest.fixture()
def valid_kwargs(fake_db):
    return dict(proposal_id="<UUID>", vendor_id="<UUID>", status="open", success_criteria="15% loss reduction in 90 days", budget_allocated=250000.0, db=fake_db)


def test_pilot_insert_payload_uses_real_fields(fake_db, valid_kwargs):
    """Happy path: payload carries the real chamber_pilots columns and the row returns."""
    fake_db.tbl("chamber_pilots").return_rows = [{"id": "row-1"}]

    row = PilotService.create_pilot(**valid_kwargs)

    assert row == {"id": "row-1"}
    assert "chamber_pilots" in fake_db.table_names

    sent = fake_db.tbl("chamber_pilots").last_insert
    assert set(sent.keys()) == {"proposal_id", "vendor_id", "status", "success_criteria", "budget_allocated"}
    assert sent["proposal_id"] == "<UUID>"
    assert sent["vendor_id"] == "<UUID>"
    assert sent["status"] == "open"
    assert sent["success_criteria"] == "15% loss reduction in 90 days"
    assert sent["budget_allocated"] == 250000.0


def test_pilot_coerces_and_warns(fake_db, valid_kwargs, caplog):
    """Lenient validation coerces `budget_allocated` and emits a warning."""
    fake_db.tbl("chamber_pilots").return_rows = [{"id": "row-2"}]
    valid_kwargs["budget_allocated"] = "123"

    with caplog.at_level(logging.WARNING, logger="pilot_service"):
        PilotService.create_pilot(**valid_kwargs)

    sent = fake_db.tbl("chamber_pilots").last_insert
    assert sent["budget_allocated"] == float(123)
    assert any("coerc" in record.message.lower() for record in caplog.records)


def test_pilot_strips_whitespace_on_status(fake_db, valid_kwargs):
    """Lenient validation trims surrounding whitespace from status."""
    fake_db.tbl("chamber_pilots").return_rows = [{"id": "row-3"}]
    valid_kwargs["status"] = "  spaced value  "

    PilotService.create_pilot(**valid_kwargs)

    assert fake_db.tbl("chamber_pilots").last_insert["status"] == "spaced value"


def test_pilot_raises_on_empty_result(fake_db, valid_kwargs):
    """An empty DB result is surfaced as a domain error."""
    fake_db.tbl("chamber_pilots").return_rows = []
    with pytest.raises(PilotServiceError):
        PilotService.create_pilot(**valid_kwargs)


def test_pilot_raises_when_client_errors(fake_db, valid_kwargs):
    """A client-side exception is wrapped in the service error type."""
    fake_db.tbl("chamber_pilots").raise_exc = RuntimeError("connection reset")
    with pytest.raises(PilotServiceError):
        PilotService.create_pilot(**valid_kwargs)
```

