import React, { useState } from 'react';
import api, { getErrorMessage } from '../lib/api';

const EMPTY_FORM = {
    name: '',
    contact_email: '',
    sector: '',
    trade_license_status: '',
    vscore: '',
    country: ''
  };

/**
 * VendorForm — create a vendor record.
 * Posts to /api/v1/vendors with an optimistic insert and rollback on failure.
 * Concurrency: sends If-Match / expected_version so the API can reject stale writes (409).
 * Validation: strict (blocks submit on bad input).
 */
const VendorForm = ({ onCreated, onError, expectedVersion = 0 }) => {
  const [form, setForm] = useState(EMPTY_FORM);
  const [errors, setErrors] = useState({});
  const [warnings, setWarnings] = useState([]);
  const [formError, setFormError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => (prev[name] ? { ...prev, [name]: undefined } : prev));
  };

  const validate = () => {
    const next = {};
    if (!String(form.name || '').trim()) next.name = 'Name is required.';
    else if (String(form.name).trim().length < 2) next.name = 'Name must be at least 2 characters.';
    if (!String(form.contact_email || '').trim()) next.contact_email = 'Contact Email is required.';
    if (form.contact_email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(form.contact_email).trim())) next.contact_email = 'Enter a valid email address.';
    if (!form.sector) next.sector = 'Select a sector.';
    if (!form.trade_license_status) next.trade_license_status = 'Select a trade license status.';
    {
      const msg = (form.vscore !== '' && Number.isNaN(Number(form.vscore))) ? 'V-Score must be a number.' : (form.vscore !== '' && (Number(form.vscore) < 0 || Number(form.vscore) > 100)) ? 'V-Score must be between 0 and 100.' : null;
      if (msg) next.vscore = msg;
    }
    if (!String(form.country || '').trim()) next.country = 'Country is required.';
    return next;
  };

  const buildPayload = () => {
    const payload = {};
    payload.name = String(form.name ?? '').trim() || null;
    payload.contact_email = String(form.contact_email ?? '').trim() || null;
    payload.sector = form.sector || null;
    payload.trade_license_status = form.trade_license_status || null;
    payload.vscore = form.vscore === '' ? null : Number(form.vscore);
    payload.country = String(form.country ?? '').trim() || null;
    return payload;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setFormError('');

    const nextErrors = validate();
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) {
      setFormError('Please fix the highlighted fields before submitting.');
      return;
    }
    const payload = buildPayload();
    setWarnings([]);

    const payloadWithVersion = { ...payload, expected_version: expectedVersion };

    const tempId = 'temp-' + Date.now();
    const optimistic = { id: tempId, ...payloadWithVersion, _optimistic: true };
    let rolledBack = false;
    // Optimistic insert — surface the row to the parent immediately.
    if (onCreated) onCreated(optimistic, { optimistic: true, tempId });
    const rollback = () => {
      if (rolledBack) return;
      rolledBack = true;
      if (onCreated) onCreated(null, { rollback: true, tempId });
    };

    setSubmitting(true);
    try {
      const { data } = await api.post(
        "/api/v1/vendors",
        payloadWithVersion,
        { headers: { 'If-Match': String(expectedVersion) } }
      );
      // Reconcile the optimistic row with the server's canonical record.
      if (onCreated) onCreated(data, { optimistic: false, tempId });
      setForm(EMPTY_FORM);
      setWarnings([]);
    } catch (err) {
      rollback();
      if (err?.response?.status === 409) {
        setFormError('This record changed since you loaded it (version conflict). Reload and try again.');
      } else {
        setFormError(getErrorMessage(err));
      }
      if (onError) onError(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate className="space-y-4 rounded-lg border border-ink/10 bg-white p-6 shadow-sm">
      <h2 className="text-xl font-heading font-bold text-ink">New Vendor</h2>

      {formError && (
        <div role="alert" className="rounded-md border border-red-300 bg-red-50 px-4 py-3 text-sm text-red-700">
          {formError}
        </div>
      )}

      {warnings.length > 0 && (
        <div role="status" className="rounded-md border border-amber-300 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          <p className="font-medium">Submitted with adjustments:</p>
          <ul className="mt-1 list-disc pl-5">
            {warnings.map((w, i) => (
              <li key={i}>{w}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <div>
          <label htmlFor="name" className="block text-sm font-medium text-ink">Name <span className="text-red-500">*</span></label>
          <input type="text" id="name" name="name" disabled={submitting} value={form.name} onChange={handleChange} placeholder={"Organization name"} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.name ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
          {errors.name && <p className="mt-1 text-xs text-red-600">{errors.name}</p>}
        </div>
        <div>
          <label htmlFor="contact_email" className="block text-sm font-medium text-ink">Contact Email <span className="text-red-500">*</span></label>
          <input type="email" id="contact_email" name="contact_email" disabled={submitting} value={form.contact_email} onChange={handleChange} placeholder={"name@company.com"} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.contact_email ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
          {errors.contact_email && <p className="mt-1 text-xs text-red-600">{errors.contact_email}</p>}
        </div>
        <div>
          <label htmlFor="sector" className="block text-sm font-medium text-ink">Sector <span className="text-red-500">*</span></label>
          <select id="sector" name="sector" disabled={submitting} value={form.sector} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.sector ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`}>
            <option value="">Select…</option>
            <option value="fintech">fintech</option>
            <option value="healthtech">healthtech</option>
            <option value="logistics">logistics</option>
            <option value="energy">energy</option>
            <option value="govtech">govtech</option>
            <option value="cybersecurity">cybersecurity</option>
          </select>
          {errors.sector && <p className="mt-1 text-xs text-red-600">{errors.sector}</p>}
        </div>
        <div>
          <label htmlFor="trade_license_status" className="block text-sm font-medium text-ink">Trade License Status <span className="text-red-500">*</span></label>
          <select id="trade_license_status" name="trade_license_status" disabled={submitting} value={form.trade_license_status} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.trade_license_status ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`}>
            <option value="">Select…</option>
            <option value="unverified">unverified</option>
            <option value="pending">pending</option>
            <option value="verified">verified</option>
            <option value="expired">expired</option>
            <option value="invalid">invalid</option>
          </select>
          {errors.trade_license_status && <p className="mt-1 text-xs text-red-600">{errors.trade_license_status}</p>}
        </div>
        <div>
          <label htmlFor="vscore" className="block text-sm font-medium text-ink">V-Score</label>
          <input type="number" step="0.1" min={0} max={100} id="vscore" name="vscore" disabled={submitting} value={form.vscore} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.vscore ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
          {errors.vscore && <p className="mt-1 text-xs text-red-600">{errors.vscore}</p>}
        </div>
        <div>
          <label htmlFor="country" className="block text-sm font-medium text-ink">Country <span className="text-red-500">*</span></label>
          <input type="text" id="country" name="country" disabled={submitting} value={form.country} onChange={handleChange} placeholder={"e.g. United Arab Emirates"} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.country ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
          {errors.country && <p className="mt-1 text-xs text-red-600">{errors.country}</p>}
        </div>
      </div>

      <div className="flex items-center justify-end gap-3 pt-2">
        <button
          type="button"
          onClick={() => { setForm(EMPTY_FORM); setErrors({}); setWarnings([]); setFormError(''); }}
          disabled={submitting}
