import React, { useState } from 'react';
import api, { getErrorMessage } from '../lib/api';

const EMPTY_FORM = {
    title: '',
    problem_statement: '',
    sector: '',
    compliance_tier: '',
    status: '',
    urgency: ''
  };

/**
 * SourcingCaseForm — create a sourcing case record.
 * Posts to /api/v1/sourcing-cases with an optimistic insert and rollback on failure.
 * Concurrency: sends If-Match / expected_version so the API can reject stale writes (409).
 * Validation: strict (blocks submit on bad input).
 */
const SourcingCaseForm = ({ onCreated, onError, expectedVersion = 0 }) => {
  const [form, setForm] = useState(EMPTY_FORM);
  const [errors, setErrors] = useState({});
  const [warnings, setWarnings] = useState([]);
  const [formError, setFormError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => (prev[name] ? { ...prev, [name]: undefined } : prev));
  };

  const validate = () => {
    const next = {};
    if (!String(form.title || '').trim()) next.title = 'Title is required.';
    else if (String(form.title).trim().length < 3) next.title = 'Title must be at least 3 characters.';
    if (!String(form.problem_statement || '').trim()) next.problem_statement = 'Problem Statement is required.';
    else if (String(form.problem_statement).trim().length < 20) next.problem_statement = 'Problem Statement must be at least 20 characters.';
    if (!form.sector) next.sector = 'Select a sector.';
    if (!form.compliance_tier) next.compliance_tier = 'Select a compliance tier.';
    if (!form.status) next.status = 'Select a status.';
    if (!form.urgency) next.urgency = 'Select a urgency.';
    return next;
  };

  const buildPayload = () => {
    const payload = {};
    payload.title = String(form.title ?? '').trim() || null;
    payload.problem_statement = String(form.problem_statement ?? '').trim() || null;
    payload.sector = form.sector || null;
    payload.compliance_tier = form.compliance_tier || null;
    payload.status = form.status || null;
    payload.urgency = form.urgency || null;
    return payload;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setFormError('');

    const nextErrors = validate();
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) {
      setFormError('Please fix the highlighted fields before submitting.');
      return;
    }
    const payload = buildPayload();
    setWarnings([]);

    const payloadWithVersion = { ...payload, expected_version: expectedVersion };

    const tempId = 'temp-' + Date.now();
    const optimistic = { id: tempId, ...payloadWithVersion, _optimistic: true };
    let rolledBack = false;
    // Optimistic insert — surface the row to the parent immediately.
    if (onCreated) onCreated(optimistic, { optimistic: true, tempId });
    const rollback = () => {
      if (rolledBack) return;
      rolledBack = true;
      if (onCreated) onCreated(null, { rollback: true, tempId });
    };

    setSubmitting(true);
    try {
      const { data } = await api.post(
        "/api/v1/sourcing-cases",
        payloadWithVersion,
        { headers: { 'If-Match': String(expectedVersion) } }
      );
      // Reconcile the optimistic row with the server's canonical record.
      if (onCreated) onCreated(data, { optimistic: false, tempId });
      setForm(EMPTY_FORM);
      setWarnings([]);
    } catch (err) {
      rollback();
      if (err?.response?.status === 409) {
        setFormError('This record changed since you loaded it (version conflict). Reload and try again.');
      } else {
        setFormError(getErrorMessage(err));
      }
      if (onError) onError(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate className="space-y-4 rounded-lg border border-ink/10 bg-white p-6 shadow-sm">
      <h2 className="text-xl font-heading font-bold text-ink">New Sourcing Case</h2>

      {formError && (
        <div role="alert" className="rounded-md border border-red-300 bg-red-50 px-4 py-3 text-sm text-red-700">
          {formError}
        </div>
      )}

      {warnings.length > 0 && (
        <div role="status" className="rounded-md border border-amber-300 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          <p className="font-medium">Submitted with adjustments:</p>
          <ul className="mt-1 list-disc pl-5">
            {warnings.map((w, i) => (
              <li key={i}>{w}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <div>
          <label htmlFor="title" className="block text-sm font-medium text-ink">Title <span className="text-red-500">*</span></label>
          <input type="text" id="title" name="title" disabled={submitting} value={form.title} onChange={handleChange} placeholder={"Short descriptive title"} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.title ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
          {errors.title && <p className="mt-1 text-xs text-red-600">{errors.title}</p>}
        </div>
        <div className="sm:col-span-2">
          <div>
            <label htmlFor="problem_statement" className="block text-sm font-medium text-ink">Problem Statement <span className="text-red-500">*</span></label>
            <textarea id="problem_statement" name="problem_statement" disabled={submitting} rows={4} value={form.problem_statement} onChange={handleChange} placeholder={"Describe the sourcing problem"} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.problem_statement ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
            {errors.problem_statement && <p className="mt-1 text-xs text-red-600">{errors.problem_statement}</p>}
          </div>
        </div>
        <div>
          <label htmlFor="sector" className="block text-sm font-medium text-ink">Sector <span className="text-red-500">*</span></label>
          <select id="sector" name="sector" disabled={submitting} value={form.sector} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.sector ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`}>
            <option value="">Select…</option>
            <option value="fintech">fintech</option>
            <option value="healthtech">healthtech</option>
            <option value="logistics">logistics</option>
            <option value="energy">energy</option>
            <option value="govtech">govtech</option>
            <option value="cybersecurity">cybersecurity</option>
          </select>
          {errors.sector && <p className="mt-1 text-xs text-red-600">{errors.sector}</p>}
        </div>
        <div>
          <label htmlFor="compliance_tier" className="block text-sm font-medium text-ink">Compliance Tier <span className="text-red-500">*</span></label>
          <select id="compliance_tier" name="compliance_tier" disabled={submitting} value={form.compliance_tier} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.compliance_tier ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`}>
            <option value="">Select…</option>
            <option value="tier_1">tier_1</option>
            <option value="tier_2">tier_2</option>
            <option value="tier_3">tier_3</option>
          </select>
          {errors.compliance_tier && <p className="mt-1 text-xs text-red-600">{errors.compliance_tier}</p>}
        </div>
        <div>
          <label htmlFor="status" className="block text-sm font-medium text-ink">Status <span className="text-red-500">*</span></label>
          <select id="status" name="status" disabled={submitting} value={form.status} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.status ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`}>
            <option value="">Select…</option>
            <option value="open">open</option>
            <option value="in_progress">in_progress</option>
            <option value="matched">matched</option>
            <option value="closed">closed</option>
          </select>
          {errors.status && <p className="mt-1 text-xs text-red-600">{errors.status}</p>}
        </div>
        <div>
          <label htmlFor="urgency" className="block text-sm font-medium text-ink">Urgency <span className="text-red-500">*</span></label>
          <select id="urgency" name="urgency" disabled={submitting} value={form.urgency} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.urgency ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`}>
            <option value="">Select…</option>
            <option value="low">low</option>
            <option value="medium">medium</option>
            <option value="high">high</option>
            <option value="critical">critical</option>
          </select>
          {errors.urgency && <p className="mt-1 text-xs text-red-600">{errors.urgency}</p>}
        </div>
      </div>

      <div className="flex items-center justify-end gap-3 pt-2">
        <button
          type="button"
          onClick={() => { setForm(EMPTY_FORM); setErrors({}); setWarnings([]); setFormError(''); }}
          disabled={submitting}
          className="rounded-md border border-ink/20 px-4 py-2 text-sm font-medium text-ink hover:bg-ink/5 disabled:opacity-50"
        >
          Reset
        </button>
        <button
          type="submit"
          disabled={submitting}
          className="inline-flex items-center rounded-md bg-teal px-4 py-2 text-sm font-semibold text-white shadow-sm hover:bg-teal/90 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {submitting ? 'Saving…' : 'Create Sourcing Case'}
        </button>
      </div>
    </form>
  );
};

