-- Migration: role-scoped RLS for chamber_proposals
-- Reviewer roles may read all proposals; only analysts and
-- admins may create or edit them (admin always allowed).

ALTER TABLE chamber_proposals ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "chamber_proposals_reviewer_select"
    ON chamber_proposals;

CREATE POLICY "chamber_proposals_reviewer_select"
    ON chamber_proposals
    FOR SELECT
    USING (
        EXISTS (
            SELECT 1
            FROM chamber_users AS u
            WHERE u.id = auth.uid()
              AND u.role IN (
                  'analyst',
                  'executive',
                  'business_group_lead',
                  'admin'
              )
        )
    );

DROP POLICY IF EXISTS "chamber_proposals_manager_insert"
    ON chamber_proposals;

CREATE POLICY "chamber_proposals_manager_insert"
    ON chamber_proposals
    FOR INSERT
    WITH CHECK (
        EXISTS (
            SELECT 1
            FROM chamber_users AS u
            WHERE u.id = auth.uid()
              AND u.role IN ('analyst', 'admin')
        )
    );

DROP POLICY IF EXISTS "chamber_proposals_manager_update"
    ON chamber_proposals;

CREATE POLICY "chamber_proposals_manager_update"
    ON chamber_proposals
    FOR UPDATE
    USING (
        EXISTS (
            SELECT 1
            FROM chamber_users AS u
            WHERE u.id = auth.uid()
              AND u.role IN ('analyst', 'admin')
        )
    )
    WITH CHECK (
        EXISTS (
            SELECT 1
            FROM chamber_users AS u
            WHERE u.id = auth.uid()
              AND u.role IN ('analyst', 'admin')
        )
    );

GRANT SELECT, INSERT, UPDATE ON chamber_proposals TO authenticated;

NOTIFY pgrst, 'reload schema';
