  };

/**
 * DescProviderForm — create a desc provider record.
 * Posts to /api/v1/desc-providers with an optimistic insert and rollback on failure.
 * No idempotency guard — the Create button is locked while a request is in flight.
 * Validation: strict (blocks submit on bad input).
 */
const DescProviderForm = ({ onCreated, onError, expectedVersion = 0 }) => {
  const [form, setForm] = useState(EMPTY_FORM);
  const [errors, setErrors] = useState({});
  const [warnings, setWarnings] = useState([]);
  const [formError, setFormError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => (prev[name] ? { ...prev, [name]: undefined } : prev));
  };

  const validate = () => {
    const next = {};
    if (!String(form.name || '').trim()) next.name = 'Name is required.';
    else if (String(form.name).trim().length < 2) next.name = 'Name must be at least 2 characters.';
    if (!form.cert_status) next.cert_status = 'Select a certification status.';
    if (!form.expiry_date) next.expiry_date = 'Expiry Date is required.';
    return next;
  };

  const buildPayload = () => {
    const payload = {};
    payload.name = String(form.name ?? '').trim() || null;
    payload.cert_status = form.cert_status || null;
    payload.expiry_date = form.expiry_date || null;
    return payload;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (submitting) return;
    setFormError('');

    const nextErrors = validate();
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) {
      setFormError('Please fix the highlighted fields before submitting.');
      return;
    }
    const payload = buildPayload();
    setWarnings([]);


    const tempId = 'temp-' + Date.now();
    const optimistic = { id: tempId, ...payload, _optimistic: true };
    let rolledBack = false;
    // Optimistic insert — surface the row to the parent immediately.
    if (onCreated) onCreated(optimistic, { optimistic: true, tempId });
    const rollback = () => {
      if (rolledBack) return;
      rolledBack = true;
      if (onCreated) onCreated(null, { rollback: true, tempId });
    };

    setSubmitting(true);
    try {
      const { data } = await api.post("/api/v1/desc-providers", payload);
      // Reconcile the optimistic row with the server's canonical record.
      if (onCreated) onCreated(data, { optimistic: false, tempId });
      setForm(EMPTY_FORM);
      setWarnings([]);
    } catch (err) {
      rollback();
      setFormError(getErrorMessage(err));
      if (onError) onError(err);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate className="space-y-4 rounded-lg border border-ink/10 bg-white p-6 shadow-sm">
      <h2 className="text-xl font-heading font-bold text-ink">New Desc Provider</h2>

      {formError && (
        <div role="alert" className="rounded-md border border-red-300 bg-red-50 px-4 py-3 text-sm text-red-700">
          {formError}
        </div>
      )}

      {warnings.length > 0 && (
        <div role="status" className="rounded-md border border-amber-300 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          <p className="font-medium">Submitted with adjustments:</p>
          <ul className="mt-1 list-disc pl-5">
            {warnings.map((w, i) => (
              <li key={i}>{w}</li>
            ))}
          </ul>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
        <div>
          <label htmlFor="name" className="block text-sm font-medium text-ink">Name <span className="text-red-500">*</span></label>
          <input type="text" id="name" name="name" disabled={submitting} value={form.name} onChange={handleChange} placeholder={"Organization name"} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.name ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
          {errors.name && <p className="mt-1 text-xs text-red-600">{errors.name}</p>}
        </div>
        <div>
          <label htmlFor="cert_status" className="block text-sm font-medium text-ink">Certification Status <span className="text-red-500">*</span></label>
          <select id="cert_status" name="cert_status" disabled={submitting} value={form.cert_status} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.cert_status ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`}>
            <option value="">Select…</option>
            <option value="active">active</option>
            <option value="pending">pending</option>
            <option value="suspended">suspended</option>
            <option value="expired">expired</option>
          </select>
          {errors.cert_status && <p className="mt-1 text-xs text-red-600">{errors.cert_status}</p>}
        </div>
        <div>
          <label htmlFor="expiry_date" className="block text-sm font-medium text-ink">Expiry Date <span className="text-red-500">*</span></label>
          <input type="date" id="expiry_date" name="expiry_date" disabled={submitting} value={form.expiry_date} onChange={handleChange} className={`mt-1 block w-full rounded-md border border-ink/20 bg-white px-3 py-2 text-sm text-ink shadow-sm focus:border-teal focus:outline-none focus:ring-1 focus:ring-teal disabled:bg-ink/5${errors.expiry_date ? ' border-red-400 focus:border-red-400 focus:ring-red-400' : ''}`} />
          {errors.expiry_date && <p className="mt-1 text-xs text-red-600">{errors.expiry_date}</p>}
        </div>
      </div>

      <div className="flex items-center justify-end gap-3 pt-2">
        <button
          type="button"
          onClick={() => { setForm(EMPTY_FORM); setErrors({}); setWarnings([]); setFormError(''); }}
          disabled={submitting}
          className="rounded-md border border-ink/20 px-4 py-2 text-sm font-medium text-ink hover:bg-ink/5 disabled:opacity-50"
        >
          Reset
        </button>
        <button
          type="submit"
          disabled={submitting}
          className="inline-flex items-center rounded-md bg-teal px-4 py-2 text-sm font-semibold text-white shadow-sm hover:bg-teal/90 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {submitting ? 'Saving…' : 'Create Desc Provider'}
        </button>
      </div>
    </form>
  );
};

export default DescProviderForm;
