  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  proposal_id uuid NOT NULL REFERENCES chamber_proposals(id) ON DELETE CASCADE,
  stage text NOT NULL CHECK (stage IN ('discovery', 'scoping', 'evaluation', 'pilot_approval', 'procurement')),
  decision text NOT NULL CHECK (decision IN ('go', 'kill', 'hold', 'recycle', 'conditional_go')),
  decided_by uuid REFERENCES chamber_users(id) ON DELETE SET NULL,
  rationale text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_chamber_gate_decisions_proposal ON chamber_gate_decisions(proposal_id);
CREATE INDEX IF NOT EXISTS idx_chamber_gate_decisions_stage ON chamber_gate_decisions(stage);
CREATE INDEX IF NOT EXISTS idx_chamber_gate_decisions_decided_by ON chamber_gate_decisions(decided_by);

DROP TRIGGER IF EXISTS set_updated_at_chamber_gate_decisions ON chamber_gate_decisions;
CREATE TRIGGER set_updated_at_chamber_gate_decisions
    BEFORE UPDATE ON chamber_gate_decisions
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();
