import { useState, useEffect, useCallback, useRef } from 'react';
import api, { getErrorMessage } from '../lib/api';

/**
 * useGateDecision - data hook for GateDecision records (table: chamber_gate_decisions).
 *
 * Uses classic offset/limit pagination against
 * GET /api/v1/gate-decisions?page=<n>&page_size=<n>.
 *
 * Exposed GateDecision fields: proposal_id, stage, decision, decided_by, rationale.
 *
 * Returns { decisions, loading, error, page, pageSize, totalPages, total,
 *   pagination, setPage, nextPage, prevPage, refetch }.
 */
export function useGateDecision({
  page: initialPage = 1,
  pageSize = 20,
  stage,
  decision
} = {}) {
  const [decisions, setDecisions] = useState([]);
  const [pagination, setPagination] = useState(null);
  const [page, setPage] = useState(initialPage);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const controllerRef = useRef(null);

  const fetchGateDecisions = useCallback(async () => {
    // Cancel any request still in flight before starting a new one.
    if (controllerRef.current) {
      controllerRef.current.abort();
    }
    const controller = new AbortController();
    controllerRef.current = controller;

    setLoading(true);
    setError(null);

    try {
      const query = new URLSearchParams();
      query.set('page', String(page));
      query.set('page_size', String(pageSize));
      if (stage != null && stage !== '') query.set('stage', String(stage));
      if (decision != null && decision !== '') query.set('decision', String(decision));

      const res = await api.get(`/api/v1/gate-decisions?${query.toString()}`, {
        signal: controller.signal
      });

      const data = res?.data ?? {};
      const rows = Array.isArray(data)
        ? data
        : (data.decisions || data.items || data.results || []);

      // Each row exposes GateDecision fields such as proposal_id.
      setDecisions(rows);
      setPagination(data.pagination ?? null);
    } catch (err) {
      // AbortController-driven cancellations are not real failures.
      if (err?.name === 'CanceledError' || err?.code === 'ERR_CANCELED' || api.isCancel?.(err)) {
        return;
      }
      setError(err?.friendly?.message || getErrorMessage(err));
      setDecisions([]);
    } finally {
      if (controllerRef.current === controller) {
        controllerRef.current = null;
        setLoading(false);
      }
    }
  }, [page, pageSize, stage, decision]);

  useEffect(() => {
    fetchGateDecisions();
    return () => {
      if (controllerRef.current) {
        controllerRef.current.abort();
        controllerRef.current = null;
      }
    };
  }, [fetchGateDecisions]);

  // Synchronous page controls for offset/limit navigation.
  const totalPages = pagination?.total_pages ?? null;
  const total = pagination?.total ?? null;

  const nextPage = useCallback(() => {
    setPage((p) => (totalPages ? Math.min(p + 1, totalPages) : p + 1));
  }, [totalPages]);

  const prevPage = useCallback(() => {
    setPage((p) => Math.max(1, p - 1));
  }, []);

  const refetch = useCallback(() => fetchGateDecisions(), [fetchGateDecisions]);

  return {
    decisions,
    loading,
    error,
    page,
    pageSize,
    totalPages,
    total,
    pagination,
    setPage,
    nextPage,
    prevPage,
    refetch
  };
}

export default useGateDecision;
