-- Row Level Security migration for chamber_alerts
-- Owner-only access: rows visible to created_by = auth.uid() (admins exempt).


ALTER TABLE chamber_alerts ENABLE ROW LEVEL SECURITY;
ALTER TABLE chamber_alerts ADD COLUMN IF NOT EXISTS created_by UUID;

DROP POLICY IF EXISTS "chamber_alerts_owner_access" ON chamber_alerts;

CREATE POLICY "chamber_alerts_owner_access" ON chamber_alerts
  FOR ALL
  USING (
    created_by = auth.uid()
    OR EXISTS (
      SELECT 1 FROM chamber_users u
      WHERE u.id = auth.uid() AND u.role = 'admin'
    )
  )
  WITH CHECK (
    created_by = auth.uid()
    OR EXISTS (
      SELECT 1 FROM chamber_users u
      WHERE u.id = auth.uid() AND u.role = 'admin'
    )
  );

GRANT SELECT, INSERT, UPDATE, DELETE ON chamber_alerts TO authenticated;

NOTIFY pgrst, 'reload schema';
