import React, { useEffect, useState, useRef, useCallback } from 'react';
import api, { getErrorMessage } from '../lib/api';

const ScoreCell = ({ value }) => {
  if (value == null || value === '') return <span className="text-gray-500">\u2014</span>;
  const n = Number(value);
  if (Number.isNaN(n)) return <span className="text-gray-500">\u2014</span>;
  const color = n >= 70 ? 'text-emerald-400 bg-emerald-500/20' : n >= 40 ? 'text-amber-400 bg-amber-500/20' : 'text-red-400 bg-red-500/20';
  return <span className={`${color} px-2 py-0.5 rounded-full text-xs font-bold`}>{n.toFixed(1)}</span>;
};

const STATUS_STYLES = {
  active: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  passed: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  completed: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  selected: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  approved: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  shortlisted: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
  in_progress: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
  pending: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
  planned: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
  paused: 'bg-orange-500/20 text-orange-400 border-orange-500/30',
  failed: 'bg-red-500/20 text-red-400 border-red-500/30',
  rejected: 'bg-red-500/20 text-red-400 border-red-500/30',
  cancelled: 'bg-red-500/20 text-red-400 border-red-500/30',
  expired: 'bg-red-500/20 text-red-400 border-red-500/30',
  suspended: 'bg-red-500/20 text-red-400 border-red-500/30',
};

const StatusPill = ({ value }) => (
  <span className={`px-3 py-1 rounded-full text-xs font-medium border ${STATUS_STYLES[value] || 'bg-gray-500/20 text-gray-400 border-gray-500/30'}`}>
    {value ? String(value).replace(/_/g, ' ') : '\u2014'}
  </span>
);

const PAGE_SIZE = 20;
const STATUS_OPTIONS = ["submitted", "under_review", "evaluated", "shortlisted", "rejected"];

const ProposalList = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [items, setItems] = useState([]);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [filterValue, setFilterValue] = useState('');

  const fetchData = useCallback(async (signal) => {
    try {
      setLoading(true);
      setError(null);
      const offset = (page - 1) * PAGE_SIZE;
      const params = new URLSearchParams();
      params.set('limit', String(PAGE_SIZE));
      params.set('offset', String(offset));
      if (filterValue) params.set('status', filterValue);
      const res = await api.get(`/api/v1/proposals?${params.toString()}`, { signal });
        const rows = res.data.proposals || [];
        setItems(rows);
        setTotal(res.data.total ?? rows.length);
        try {
          await api.post('/api/v1/audit-logs', { action: 'list', resource: 'proposal', count: rows.length }, { signal });
        } catch (auditErr) {
          if (auditErr?.name !== 'CanceledError' && auditErr?.code !== 'ERR_CANCELED') {
            console.warn('audit log write failed', auditErr?.message);
          }
        }
    } catch (err) {
      if (err?.code === 'ERR_CANCELED' || err?.name === 'CanceledError' || err?.name === 'AbortError') return;
      setError(getErrorMessage(err));
    } finally {
      if (!signal.aborted) setLoading(false);
    }
  }, [page, filterValue]);

  useEffect(() => {
    const controller = new AbortController();
    fetchData(controller.signal);
    return () => controller.abort();
  }, [fetchData]);

  const onFilterChange = useCallback((e) => {
    setFilterValue(e.target.value);
    setPage(1);
  }, []);

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));


  return (
    <div className="min-h-screen bg-[var(--color-table-header-bg)] p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        <header className="mb-6 flex flex-wrap items-center justify-between gap-4">
          <h1 className="text-3xl font-bold text-white">Proposal</h1>
          <select
            value={filterValue}
            onChange={onFilterChange}
            className="bg-[#1E293B] text-gray-300 border border-gray-700 rounded-lg px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#3B82F6]"
          >
            <option value="">All status</option>
            {STATUS_OPTIONS.map((opt) => (
              <option key={opt} value={opt}>{opt.replace(/_/g, ' ')}</option>
            ))}
          </select>
        </header>

        {error && (
          <div className="bg-red-500/10 border border-red-500/30 rounded-lg p-4 mb-6" role="alert">
            <p className="text-red-400">{error}</p>
          </div>
        )}

        <div className="bg-[#1E293B] rounded-xl overflow-hidden shadow-xl">
          {loading ? (
            <div className="p-12 text-center">
              <div className="animate-spin rounded-full h-10 w-10 border-t-2 border-b-2 border-[#3B82F6] mx-auto mb-4"></div>
              <p className="text-gray-400">Loading proposal...</p>
            </div>
          ) : (
            <div style={{ overflowX: 'auto', width: '100%' }}>
              <table className="w-full" style={{ minWidth: '720px' }}>
                <thead className="bg-[var(--color-table-header-bg)] border-b border-gray-700">
                  <tr>
                  <th className="text-left p-4 text-gray-400 font-medium text-sm">Title</th>
                  <th className="text-left p-4 text-gray-400 font-medium text-sm">Status</th>
                  <th className="text-left p-4 text-gray-400 font-medium text-sm">Sector</th>
                  <th className="text-left p-4 text-gray-400 font-medium text-sm">Technology Type</th>
                  <th className="text-left p-4 text-gray-400 font-medium text-sm">Composite Score</th>
                  <th className="text-left p-4 text-gray-400 font-medium text-sm">Submitter Id</th>
                  <th className="text-left p-4 text-gray-400 font-medium text-sm">Sourcing Case Id</th>
                  </tr>
                </thead>
                <tbody>
                  {items.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="text-center p-12 text-gray-500">No records found</td>
                    </tr>
                  ) : (
                    items.map((row) => (
                      <tr key={row.id} className="border-b border-gray-700/50 hover:bg-[var(--color-table-header-bg)] transition-colors">
                      <td className="p-4 text-gray-300 text-sm">{row.title != null && row.title !== '' ? String(row.title) : '\u2014'}</td>
                      <td className="p-4"><StatusPill value={row.status} /></td>
                      <td className="p-4 text-gray-300 text-sm">{row.sector != null && row.sector !== '' ? String(row.sector) : '\u2014'}</td>
                      <td className="p-4 text-gray-300 text-sm">{row.technology_type != null && row.technology_type !== '' ? String(row.technology_type) : '\u2014'}</td>
                      <td className="p-4"><ScoreCell value={row.composite_score} /></td>
                      <td className="p-4 text-gray-300 text-sm">{row.submitter_id != null && row.submitter_id !== '' ? String(row.submitter_id) : '\u2014'}</td>
                      <td className="p-4 text-gray-300 text-sm">{row.sourcing_case_id != null && row.sourcing_case_id !== '' ? String(row.sourcing_case_id) : '\u2014'}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {!loading && (
        <div className="flex items-center justify-between mt-6">
          <button
            type="button"
            onClick={() => setPage((p) => Math.max(1, p - 1))}
            disabled={page === 1 || loading}
            className="px-4 py-2 rounded-lg bg-[#1E293B] text-gray-300 border border-gray-700 disabled:opacity-40 hover:bg-gray-700 transition"
          >
            Previous
          </button>
          <span className="text-gray-500 text-sm">Page {page} of {totalPages} ({total} total)</span>
          <button
            type="button"
            onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
            disabled={page >= totalPages || loading}
            className="px-4 py-2 rounded-lg bg-[#1E293B] text-gray-300 border border-gray-700 disabled:opacity-40 hover:bg-gray-700 transition"
          >
            Next
          </button>
        </div>
        )}
      </div>
    </div>
  );
};

export default ProposalList;
